# Excel-bouw
# ---------------------------------------------------------------------------
DATASETS = [
    ("100-voorbeeldvragen-inkoopbeleid-VV-2027-2029.xlsx",
     "Inkoopbeleid Wlz Verpleging & Verzorging 2027-2029", VV),
    ("100-voorbeeldvragen-inkoopbeleid-GZ-2027-2029.xlsx",
     "Inkoopbeleid Wlz Gehandicaptenzorg 2027-2029", GZ),
    ("100-voorbeeldvragen-inkoopbeleid-GGZ-2027-2029.xlsx",
     "Inkoopbeleid Wlz GGZ 2027-2029", GGZ),
    ("100-voorbeeldvragen-bijlage-7-onderbouwing-vertrektarieven-Wlz-2027.xlsx",
     "Bijlage 7: Onderbouwing vertrektarieven Wlz 2027", B7),
]

HEADER_FILL = PatternFill("solid", fgColor="1F4E78")
HEADER_FONT = Font(bold=True, color="FFFFFF", size=11)
TITLE_FONT = Font(bold=True, size=13, color="1F4E78")
THIN = Side(style="thin", color="BFBFBF")
BORDER = Border(left=THIN, right=THIN, top=THIN, bottom=THIN)
WRAP_TOP = Alignment(wrap_text=True, vertical="top")
CENTER = Alignment(horizontal="center", vertical="top")

COLS = ["Nr.", "Document", "Hoofdstuk", "Paragraaf", "Onderwerp", "Vraag", "Antwoord zorgkantoor"]
WIDTHS = [5, 42, 34, 11, 30, 80, 40]

def build(filename, doctitle, rows):
    assert len(rows) >= 100, f"{filename}: slechts {len(rows)} vragen (<100)"
    rows = rows[:100]
    wb = Workbook()
    ws = wb.active
    ws.title = "Voorbeeldvragen"

    # Titelregel
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=len(COLS))
    t = ws.cell(row=1, column=1,
                value=f"100 voorbeeldvragen (stijl Nota van Inlichtingen) — {doctitle}")
    t.font = TITLE_FONT
    t.alignment = Alignment(vertical="center")
    ws.row_dimensions[1].height = 26

    # Kolomkoppen
    hr = 2
    for c, name in enumerate(COLS, start=1):
        cell = ws.cell(row=hr, column=c, value=name)
        cell.fill = HEADER_FILL
        cell.font = HEADER_FONT
        cell.alignment = Alignment(wrap_text=True, vertical="center",
                                   horizontal="center")
        cell.border = BORDER
    ws.row_dimensions[hr].height = 28

    # Data
    for i, (hfdst, para, onderw, vraag) in enumerate(rows, start=1):
        r = hr + i
        vals = [i, doctitle, hfdst, para, onderw, vraag, ""]
        for c, v in enumerate(vals, start=1):
            cell = ws.cell(row=r, column=c, value=v)
            cell.border = BORDER
            cell.alignment = CENTER if c in (1, 4) else WRAP_TOP

    for c, w in enumerate(WIDTHS, start=1):
        ws.column_dimensions[chr(64 + c)].width = w

    ws.freeze_panes = "A3"
    ws.auto_filter.ref = f"A2:G{hr + len(rows)}"
    wb.save(filename)
    print(f"OK  {filename}  ({len(rows)} vragen)")

for fn, title, rows in DATASETS:
    build(fn, title, rows)
print("Klaar.")
